package in.jharkhand.civic.controller;import in.jharkhand.civic.service.WorkflowService;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.nio.file.*;import org.springframework.security.core.Authentication;import org.springframework.security.access.prepost.PreAuthorize;import java.util.*;
@RestController @RequestMapping("/api/projects") public class FieldTestController{private final WorkflowService w;public FieldTestController(WorkflowService w){this.w=w;}@GetMapping("/{id}/field-tests")List<Map<String,Object>> all(@PathVariable String id){return w.fieldTests(id);}@PostMapping("/{id}/field-tests") @PreAuthorize("hasAnyRole('ADMIN','DEPARTMENT','INSTITUTION')")Map<String,Object> add(@PathVariable String id,@RequestBody Map<String,Object> r,Authentication a){return w.fieldTest(a.getName(),id,r);}@PostMapping(value="/{id}/field-tests/upload",consumes="multipart/form-data") @PreAuthorize("hasAnyRole('ADMIN','DEPARTMENT','INSTITUTION')") Map<String,Object> upload(@PathVariable String id,@RequestPart("payload") String payload,@RequestPart(value="files",required=false) List<MultipartFile> files,Authentication a)throws Exception{Map<String,Object> r=new com.fasterxml.jackson.databind.ObjectMapper().readValue(payload,Map.class);List<String> saved=new ArrayList<>();Path dir=Paths.get(w.dataDir().toString(),"uploads","field-tests",id);Files.createDirectories(dir);if(files!=null)for(MultipartFile f:files){if(f==null||f.isEmpty())continue;String n=Path.of(Optional.ofNullable(f.getOriginalFilename()).orElse("evidence")).getFileName().toString();String l=n.toLowerCase();if(!(l.endsWith(".jpg")||l.endsWith(".jpeg")||l.endsWith(".png")||l.endsWith(".webp")||l.endsWith(".pdf")||l.endsWith(".doc")||l.endsWith(".docx")))throw new RuntimeException("Unsupported evidence type");if(f.getSize()>10*1024*1024)throw new RuntimeException("Evidence file too large; maximum 10 MB");Files.copy(f.getInputStream(),dir.resolve(n),StandardCopyOption.REPLACE_EXISTING);saved.add(n);}r.put("evidence",saved);return w.fieldTest(a.getName(),id,r);}
@PostMapping("/field-tests/{id}/verify") @PreAuthorize("hasRole('ADMIN')")Map<String,Object> verify(@PathVariable String id,Authentication a){return w.verifyFieldTest(a.getName(),"ADMIN",id);}}
